import { useEffect, useState } from "react";
import axios from "axios";
import {
  Button,
  Grid,
  Input,
  MenuItem,
  Select,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Box,
  Typography,
} from "@mui/material";

const ImageUpload = () => {
  const [sliderImages, setSliderImages] = useState([]);
  const [bigPhotoImages, setBigPhotoImages] = useState([]);
  const [allPhotos, setAllPhotos] = useState([]);
  const [getAllPhotos, setGetAllPhotos] = useState([]);
  const [getBigPhoto, setGetBigPhoto] = useState([]);
  const [getSlider, setGetSlider] = useState([]);
  const [selectedCategory, setSelectedCategory] = useState("allphoto");
  const [openGallery, setOpenGallery] = useState(false);

  const handleFileChange = (e, type) => {
    if (e.target.files) {
      const filesArray = Array.from(e.target.files);
      if (type === "slider") setSliderImages(filesArray);
      else if (type === "bigphoto") setBigPhotoImages(filesArray);
      else if (type === "allphoto") setAllPhotos(filesArray);
    }
  };

  const handleUpload = async () => {
    const formData = new FormData();
    sliderImages.forEach((file) => formData.append("slider", file));
    bigPhotoImages.forEach((file) => formData.append("bigphoto", file));
    allPhotos.forEach((file) => formData.append("allphoto", file));

    try {
      const response = await axios.post("http://localhost:5000/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      console.log("Upload success:", response.data);
    } catch (error) {
      console.error("Error uploading images:", error);
    }
  };

  useEffect(() => {
    const fetchImages = async () => {
      try {
        const response = await axios.get("http://localhost:5000/images");
        setGetAllPhotos(response.data?.[0].allphoto);
        setGetBigPhoto(response.data?.[0].bigphoto);
        setGetSlider(response.data?.[0].slider);
      } catch (error) {
        console.error("Error fetching images:", error);
      }
    };
    fetchImages();
  }, []);

  const handleGalleryOpen = () => setOpenGallery(true);
  const handleGalleryClose = () => setOpenGallery(false);

  const getSelectedImages = () => {
    if (selectedCategory === "allphoto") return getAllPhotos;
    if (selectedCategory === "bigphoto") return getBigPhoto;
    if (selectedCategory === "slider") return getSlider;
    return [];
  };

  return (
    <Box sx={{ p: 4 }}>
      <Typography variant="h5" sx={{ mb: 2 }}>
        Upload Images
      </Typography>

      <Grid container spacing={2}>
        {["slider", "bigphoto", "allphoto"].map((category) => (
          <Grid item xs={12} md={4} key={category}>
            <Typography variant="subtitle1" sx={{ mb: 1, textTransform: "capitalize" }}>
              {category.replace("photo", " Photo")}
            </Typography>
            <Input
              type="file"
              multiple
              inputProps={{ accept: "image/*" }}
              onChange={(e) => handleFileChange(e, category)}
              sx={{ display: "block" }}
            />
          </Grid>
        ))}
      </Grid>

      <Button
        variant="contained"
        color="primary"
        onClick={handleUpload}
        sx={{ mt: 3 }}
      >
        Upload
      </Button>

      {/* Image Category Dropdown */}
      <Typography variant="h6" sx={{ mt: 4, mb: 1 }}>
        View Uploaded Images
      </Typography>
      <Select
        value={selectedCategory}
        onChange={(e) => setSelectedCategory(e.target.value)}
        displayEmpty
        sx={{ minWidth: 200 }}
      >
        <MenuItem value="allphoto">All Photos</MenuItem>
        <MenuItem value="bigphoto">Big Photos</MenuItem>
        <MenuItem value="slider">Slider Images</MenuItem>
      </Select>

      <Button
        variant="outlined"
        color="secondary"
        onClick={handleGalleryOpen}
        sx={{ ml: 2 }}
      >
        Open Gallery
      </Button>

      {/* Gallery Popup */}
      <Dialog open={openGallery} onClose={handleGalleryClose} maxWidth="md" fullWidth>
        <DialogTitle>Gallery - {selectedCategory.replace("photo", " Photo")}</DialogTitle>
        <DialogContent>
          <Grid container spacing={2}>
            {getSelectedImages().length > 0 ? (
              getSelectedImages().map((img, index) => (
                <Grid item xs={6} md={3} key={index}>
                  <img
                    src={img.url}
                    alt={`Uploaded ${index}`}
                    style={{
                      width: "100%",
                      height: "120px",
                      objectFit: "cover",
                      borderRadius: "8px",
                    }}
                  />
                </Grid>
              ))
            ) : (
              <Typography sx={{ p: 2 }}>No images found.</Typography>
            )}
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleGalleryClose} color="error">
            Close
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ImageUpload;
